import { Injectable } from '@angular/core';
import { SemiFinished } from '../pages/semi-finished/semi-finished';
import { HttpClient } from '@angular/common/http';
import { Observable } from 'rxjs';
import { environment } from '../environments/environments';
export interface SemiFinishedInward {
  id: number;
  semiFinishedId: number;
  semiFinished?: SemiFinished;
  batchNo: string;
  inwardDate: string;
  bags: number;
  perKg: number;
  grossQty: number;
  grossTotalQty: number;
  isFinished: boolean;
  isOutside: boolean;
}

@Injectable({
  providedIn: 'root'
})
export class SemiFinishedInwardService {
  private apiUrl = `${environment.apiUrl}/semifinishedinward`; 
  constructor(private http: HttpClient) {}

  getInwards(): Observable<SemiFinishedInward[]> {
    return this.http.get<SemiFinishedInward[]>(this.apiUrl);
  }
  getInwardByID(id: number): Observable<SemiFinishedInward> {
    return this.http.get<SemiFinishedInward>(`${this.apiUrl}/${id}`)
  }
  addInward(product: SemiFinishedInward): Observable<SemiFinishedInward> {
  return this.http.post<SemiFinishedInward>(`${this.apiUrl}/create`, product);
}

updateInward(id: number, product: SemiFinishedInward): Observable<SemiFinishedInward> {
  return this.http.put<SemiFinishedInward>(`${this.apiUrl}/update/${id}`, product);
}

deleteInward(id: number): Observable<void> {
  
  return this.http.delete<void>(`${this.apiUrl}/${id}`);
}
}
